<script setup>
import AccessibleButton from '../../components/AccessibleButton.vue'
import AccessibleDialog from '../../components/AccessibleDialog.vue'
import Toast from '../../components/Toast.vue'
import {useToast} from '../../composables/useToast'
import {ref} from 'vue';import {onShow,onUnload} from '@dcloudio/uni-app';import {request,http} from '../../utils/request';import {API_BASE_URL} from '../../utils/config';
const toast=useToast()
const rows=ref([]),busy=ref(false),saving=ref(''),error=ref(''),more=ref(false);let active=true;
const pending=ref(null),deleting=ref(false),deleteError=ref('');
async function load(append=false){if(busy.value)return;busy.value=true;error.value='';try{const list=await request({url:'/api/media/mine',data:append?{before:rows.value.at(-1)?.id}:{}});if(active){rows.value=append?[...rows.value,...list]:list;more.value=list.length===50}}catch(e){error.value=e.message}finally{busy.value=false}}
async function save(item){if(saving.value)return;saving.value=item.id;error.value='';try{const data=await request({url:'/api/media/'+item.id+'/playback'});const url=API_BASE_URL+data.url;
// #ifdef H5
const res=await fetch(url);if(!res.ok)throw Error('文件已失效，请刷新重试');const blob=await res.blob();if(!active)return;const object=URL.createObjectURL(blob),link=document.createElement('a');link.href=object;link.download='zhiyu-'+item.id+(item.kind==='video'?'.mp4':blob.type==='image/png'?'.png':blob.type==='image/webp'?'.webp':'.jpg');document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(object),30000);
// #endif
// #ifdef MP-WEIXIN
const downloaded=await new Promise((resolve,reject)=>uni.downloadFile({url,success:r=>r.statusCode===200?resolve(r):reject(Error('文件读取失败')),fail:reject}));if(!active)return;await new Promise((resolve,reject)=>(item.kind==='video'?uni.saveVideoToPhotosAlbum:uni.saveImageToPhotosAlbum)({filePath:downloaded.tempFilePath,success:resolve,fail:reject}));
// #endif
toast.show('已发起保存');
}catch(e){error.value=e.message||'保存失败，请检查网络和相册权限后重试'}finally{saving.value=''}}
function askDelete(item){pending.value=item;deleteError.value=''}
function closeDelete(){if(deleting.value)return;pending.value=null;deleteError.value=''}
async function confirmDelete(){if(deleting.value||!pending.value)return;deleting.value=true;deleteError.value='';const target=pending.value;try{await http.del('/api/media/'+target.id);if(!active)return;rows.value=rows.value.filter(r=>r.id!==target.id);pending.value=null;toast.show('已删除')}catch(e){if(!active)return;if(e.code!==1002)deleteError.value=e.code===3001?'这个文件正被作品或创作步骤使用，请先在对应作品中移除或更换后再删除。':e.code===-1?'网络异常，请检查网络连接后重试。':'删除失败，请稍后重试。'}finally{deleting.value=false}}
onShow(()=>load());onUnload(()=>{active=false})
</script>
<template><view :class="zyThemeClass" class="growth-page"><view class="growth-hero"><text class="growth-eyebrow">个人资料 · 媒体副本</text><text class="growth-title">保存自己的创作</text><text class="growth-subtitle">这里仅展示本人上传的受保护图片和视频。下载后的副本由你自行保管。</text></view><view v-if="error" class="growth-error" role="alert">{{error}}<AccessibleButton :disabled="busy" @click="load()">重新读取</AccessibleButton></view><view v-if="!rows.length&&!busy&&!error" class="growth-card"><text class="growth-card-title">还没有可保存的媒体</text><text class="growth-muted">新上传的作品图片与视频会出现在这里。早期公开图片请从原作品页保存。</text></view><view v-for="m in rows" :key="m.id" class="growth-card media-row"><view class="media-info"><text class="growth-card-title">{{m.kind==='video'?'原创视频':'创作图片'}}</text><text class="growth-muted">{{(m.size_bytes/1048576).toFixed(2)}} MB · {{String(m.create_time).slice(0,10)}}</text></view><view class="media-actions"><AccessibleButton class="growth-button" :disabled="!!saving||deleting" @click="save(m)">{{saving===m.id?'准备文件…':'保存原文件'}}</AccessibleButton><AccessibleButton class="growth-button danger" :disabled="!!saving||deleting" :ariaLabel="'删除这条'+(m.kind==='video'?'原创视频':'创作图片')" @click="askDelete(m)">删除</AccessibleButton></view></view><AccessibleButton v-if="more" :disabled="busy" @click="load(true)">加载更多</AccessibleButton><AccessibleDialog :open="!!pending" :busy="deleting" title="删除媒体文件" @close="closeDelete"><text class="dialog-description">将删除这个{{pending&&pending.kind==='video'?'视频':'图片'}}文件，删除后无法恢复；已保存到相册的副本不受影响。</text><text v-if="deleteError" class="dialog-error" role="alert">{{deleteError}}</text><view class="dialog-actions"><AccessibleButton class="dialog-secondary" :disabled="deleting" @click="closeDelete">再想想</AccessibleButton><AccessibleButton class="dialog-danger" :loading="deleting" @click="confirmDelete">{{deleting?'正在删除…':'确认删除'}}</AccessibleButton></view></AccessibleDialog><text class="growth-foot">本系统不能替代专业心理咨询</text><Toast/></view></template>
<style scoped>.media-row{display:flex;justify-content:space-between;align-items:center;gap:20rpx}.media-row button{flex-shrink:0;margin:0;font-size:var(--zy-text-caption, 24rpx)}.media-info{min-width:0}.media-actions{display:flex;gap:16rpx;flex-shrink:0;flex-wrap:wrap;justify-content:flex-end}.dialog-description{display:block;font-size:var(--zy-text-body, 28rpx);line-height:1.9;color:var(--zy-secondary,#4a5f54)}.dialog-error{display:block;color:var(--zy-care,var(--zy-care, #a64842));font-size:var(--zy-text-body, 28rpx);line-height:1.8;margin-top:24rpx}.dialog-actions{display:flex;gap:24rpx;margin-top:32rpx}.dialog-actions button{flex:1;margin:0;font-size:var(--zy-text-body, 28rpx)}.dialog-secondary{background:var(--zy-bg, #ffffff);color:var(--zy-title,#233d34);border:1rpx solid var(--zy-border,#dfe7dc)}.dialog-danger{background:var(--zy-care,var(--zy-care, #a64842));color:#fff}@media(max-width:480px){.media-row{flex-direction:column;align-items:flex-start}.media-actions{width:100%;justify-content:flex-start}}</style>
